parameters.jsCode:
return items.map(item => {
  const data = item.json;

  const requiredFields = [
    "Order_ID",
    "Date",
    "Product",
    "Category",
    "Region",
    "Customer",
    "Quantity",
    "Revenue",
    "Cost"
  ];

  const missingFields = requiredFields.filter(
    field =>
      data[field] === undefined ||
      data[field] === null ||
      data[field] === ""
  );

  const quantity = Number(data.Quantity);
  const revenue = Number(data.Revenue);
  const cost = Number(data.Cost);

  let validationStatus = "Valid";
  const errors = [];

  if (missingFields.length > 0) {
    validationStatus = "Invalid";
    errors.push(`Missing fields: ${missingFields.join(", ")}`);
  }

  if (isNaN(quantity) || quantity < 0) {
    validationStatus = "Invalid";
    errors.push("Invalid Quantity");
  }

  if (isNaN(revenue) || revenue < 0) {
    validationStatus = "Invalid";
    errors.push("Invalid Revenue");
  }

  if (isNaN(cost) || cost < 0) {
    validationStatus = "Invalid";
    errors.push("Invalid Cost");
  }

  return {
    json: {
      ...data,
      Validation_Status: validationStatus,
      Validation_Errors: errors.join("; ")
    }
  };
});

return items.map(item => {
  const data = item.json;

  const quantity = Number(data.Quantity || 0);
  const revenue = Number(data.Revenue || 0);
  const cost = Number(data.Cost || 0);

  const profit = revenue - cost;

  const profitMargin =
    revenue > 0
      ? (profit / revenue) * 100
      : 0;

  const profitPerUnit =
    quantity > 0
      ? profit / quantity
      : 0;

  return {
    json: {
      ...data,

      Revenue: Number(revenue.toFixed(2)),
      Cost: Number(cost.toFixed(2)),
      Profit: Number(profit.toFixed(2)),
      Profit_Margin: Number(profitMargin.toFixed(2)),
      Profit_Per_Unit: Number(profitPerUnit.toFixed(2))
    }
  };
});

return items.map(item => {
  const data = item.json;

  const profit = Number(data.Profit || 0);
  const margin = Number(data.Profit_Margin || 0);

  let status;
  let severity;

  if (profit < 0) {
    status = "Loss";
    severity = "Critical";
  } else if (margin < 10) {
    status = "Low Profit";
    severity = "High";
  } else if (margin < 25) {
    status = "Moderate Profit";
    severity = "Medium";
  } else {
    status = "High Profit";
    severity = "Low";
  }

  return {
    json: {
      ...data,
      Profitability_Status: status,
      Severity: severity
    }
  };
});

