parameters.jsCode:
return items.map(item => {
  const data = item.json;

  let aiResult = {};

  try {
    if (typeof data.output === "string") {
      aiResult = JSON.parse(data.output);
    } else if (data.output && typeof data.output === "object") {
      aiResult = data.output;
    }
  } catch (error) {
    aiResult = {
      analysis_status: "AI parsing failed",
      issue_type: "Unknown",
      severity: data.Severity || "Unknown",
      summary: data.output || "",
      possible_reason: "",
      business_impact: "",
      recommended_action: ""
    };
  }

  return {
    json: {
      Order_ID: data.Order_ID,
      Date: data.Date,
      Product: data.Product,
      Category: data.Category,
      Region: data.Region,
      Customer: data.Customer,
      Quantity: data.Quantity,
      Revenue: data.Revenue,
      Cost: data.Cost,
      Profit: data.Profit,
      Profit_Margin: data.Profit_Margin,
      Profit_Per_Unit: data.Profit_Per_Unit,
      Profitability_Status: data.Profitability_Status,
      Severity: aiResult.severity || data.Severity,
      AI_Analysis_Status: aiResult.analysis_status || "",
      Issue_Type: aiResult.issue_type || "",
      AI_Summary: aiResult.summary || "",
      Possible_Reason: aiResult.possible_reason || "",
      Business_Impact: aiResult.business_impact || "",
      Recommended_Action: aiResult.recommended_action || ""
    }
  };
});
